            let montant = form.get("amount").and_then(|s| s.parse::<u64>().ok()).unwrap_or(0);
            if montant == 0 { return HttpResponse::redirect("/afri-rich?msg=⚠️ Montant invalide"); }
            let mut chain = state.chain.lock().unwrap();
